<template><section class="device-operations">
 <div class="device-op-toolbar"><input v-model="search" :placeholder="mode==='apps'?'搜索应用名称或包名':'搜索进程名称、包名或 PID'" aria-label="搜索管理列表"/><select v-model="filter" aria-label="管理列表筛选"><option value="user">用户{{mode==='apps'?'应用':'进程'}}</option><option value="all">全部</option><option v-if="mode==='apps'" value="system">系统应用</option><option v-if="mode==='apps'" value="disabled">已禁用</option><option v-if="mode==='apps'" value="running">运行中</option></select><select v-if="mode==='processes'" v-model="sort" aria-label="进程排序"><option value="rss">内存从高到低</option><option value="pid">PID 从小到大</option><option value="name">名称排序</option></select><label class="device-op-check" v-if="mode==='processes'"><input type="checkbox" v-model="auto"/>自动刷新</label><button @click="load" :disabled="loading||busy">{{loading?'读取中…':'刷新'}}</button><button v-if="mode==='apps'&&auth.canFileLibrary" @click="$emit('files')">安装 APK / 管理文件</button></div>
 <div class="device-op-summary"><span>{{filtered.length}} / {{items.length}} 项</span><span v-if="mode==='processes'&&memory.MemAvailable">可用内存 {{size(memory.MemAvailable)}} / {{size(memory.MemTotal)}}</span><span v-if="updated">更新于 {{new Date(updated).toLocaleTimeString('zh-CN')}}</span></div>
 <p class="device-op-feedback" role="status" :class="{error}">{{notice}}</p><div v-if="loading&&!items.length" class="phone-manager-empty">正在读取{{mode==='apps'?'应用':'进程'}}…</div><div v-else-if="!filtered.length" class="phone-manager-empty">没有匹配项目，可切换筛选或刷新列表。</div>
 <div class="device-op-list"><article class="device-op-row" v-for="item in pageItems" :key="mode==='apps'?item.package:item.pid">
  <div class="device-op-avatar" :class="{system:item.protected}">{{mode==='apps'?'APP':'PID'}}</div><div class="device-op-main"><strong>{{mode==='apps'?item.name:item.app_name||item.name}}</strong><code>{{mode==='apps'?item.package:item.package||'未确认应用归属'}}</code><div class="device-op-meta"><template v-if="mode==='apps'"><span>{{item.system?'系统应用':'用户应用'}}</span><span>{{item.enabled?'已启用':'已禁用'}}</span><span>{{item.running?'运行中':'未运行'}}</span><span v-if="item.version_code">版本代码 {{item.version_code}}</span></template><template v-else><span>PID {{item.pid}} · UID {{item.uid}}</span><span>RSS {{size(item.rss_kb)}}</span><span>{{processState(item.state)}}</span></template></div></div>
  <div class="device-op-actions" v-if="mode==='apps'"><button @click="details(item)" :disabled="busy">详情</button><button @click="act(item,'launch')" :disabled="busy||!item.enabled">打开</button><button @click="act(item,'force_stop')" :disabled="busy||item.protected" :title="item.protected?'系统组件仅提供查看与打开':'强制停止该应用及其后台服务'">停止</button><button @click="act(item,item.enabled?'disable':'enable')" :disabled="busy||item.protected">{{item.enabled?'禁用':'启用'}}</button><button class="danger" @click="act(item,'uninstall')" :disabled="busy||item.protected">卸载</button></div>
  <div class="device-op-actions" v-else><button @click="appFromProcess(item)" :disabled="!item.package||busy">应用详情</button><button class="danger" @click="act(item,'force_stop')" :disabled="busy||item.protected||!item.package" :title="item.protected?'系统、远控或无法确认归属的进程仅查看':'停止所属应用及其全部进程'">停止应用</button></div>
 </article></div>
 <footer class="device-op-pagination" v-if="filtered.length>50"><button @click="page--" :disabled="page<=1">上一页</button><span>{{page}} / {{Math.ceil(filtered.length/50)}}</span><button @click="page++" :disabled="page*50>=filtered.length">下一页</button></footer>
 <p class="device-op-note" v-if="mode==='processes'">内存为进程 RSS 快照，不代表独占内存；“停止应用”会结束其全部相关进程。系统、远控和归属不明确的进程只提供查看。</p>
 <div v-if="detail" class="device-op-modal-overlay" @click.self="detail=null"><section class="device-op-modal" role="dialog" aria-modal="true" aria-label="应用详情"><header><h3>{{detail.name||detail.package}}</h3><button @click="detail=null" aria-label="关闭应用详情">×</button></header><code>{{detail.package}}</code><p v-if="detail.loading">正在读取应用详情…</p><pre>{{detail.details?.join('\n')}}</pre><button @click="detail=null">关闭</button></section></div>
</section></template>
<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue'
import {useAuthStore} from '@/stores/auth'
const props=defineProps({deviceId:String,mode:String});defineEmits(['files']);const auth=useAuthStore()
const items=ref([]),memory=ref({}),search=ref(''),filter=ref('user'),sort=ref('rss'),auto=ref(false),loading=ref(false),busy=ref(false),notice=ref(''),error=ref(false),updated=ref(''),page=ref(1),detail=ref(null)
let generation=0,controller,disposed=false,timer
const filtered=computed(()=>{const q=search.value.toLowerCase().trim();const a=items.value.filter(i=>(filter.value==='all'||filter.value==='user'&&(props.mode==='apps'?!i.system:!i.protected)||filter.value==='system'&&i.system||filter.value==='disabled'&&!i.enabled||filter.value==='running'&&i.running)&&(!q||[i.package,i.name,i.app_name,String(i.pid||'')].some(v=>v?.toLowerCase().includes(q))));return a.sort((a,b)=>props.mode==='processes'&&sort.value==='rss'?b.rss_kb-a.rss_kb:props.mode==='processes'&&sort.value==='pid'?a.pid-b.pid:String(a.name).localeCompare(String(b.name),'zh-CN'))})
const pageItems=computed(()=>filtered.value.slice((page.value-1)*50,page.value*50))
function size(kb){if(!Number.isFinite(kb)||kb<0)return '—';return kb>=1048576?(kb/1048576).toFixed(2)+' GiB':kb>=1024?(kb/1024).toFixed(1)+' MiB':kb+' KiB'}
function processState(value){const v=String(value||'')[0];return({R:'运行',S:'休眠',D:'等待 I/O',I:'空闲',T:'暂停',Z:'僵尸'})[v]||value||'未知'}
async function request(query='',body,signal){const r=await fetch('/api/devices/'+encodeURIComponent(props.deviceId)+'/management'+query,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal,cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'设备管理请求失败');return d}
async function load(){if(!props.deviceId||busy.value)return;const g=++generation;controller?.abort();controller=new AbortController();loading.value=true;try{const d=await request('?view='+props.mode,undefined,controller.signal);if(disposed||g!==generation)return;items.value=d.items||[];memory.value=d.memory_kb||{};updated.value=d.checked_at;error.value=false;page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/50)))}catch(e){if(g===generation&&e.name!=='AbortError'){notice.value=e.message;error.value=true}}finally{if(g===generation)loading.value=false}}
async function act(item,action){const device=props.deviceId;const pkg=item.package;const labels={force_stop:'停止',uninstall:'卸载并删除本机数据',disable:'禁用',enable:'启用'};if(action!=='launch'&&!confirm(`确认${labels[action]}应用“${pkg}”？${action==='force_stop'?'该应用的相关进程和后台服务也会停止。':''}`))return;if(device!==props.deviceId){notice.value='设备已变化，请刷新后重试';return}busy.value=true;error.value=false;try{const body={package:pkg,action};if(props.mode==='processes'){body.pid=item.pid;body.name=item.name}await request('',body);if(device===props.deviceId)notice.value='操作已完成：'+pkg}catch(e){if(device===props.deviceId){notice.value=e.message;error.value=true}}finally{busy.value=false;await load()}}
async function details(item){const id=props.deviceId;detail.value={...item,loading:true};try{const d=await request('?view=details&package='+encodeURIComponent(item.package));if(detail.value?.package===item.package&&props.deviceId===id)detail.value={...item,...d,loading:false}}catch(e){if(detail.value?.package===item.package&&props.deviceId===id)detail.value={...item,details:[e.message],loading:false}}}
function appFromProcess(item){details({package:item.package,name:item.package})}
watch(()=>[props.deviceId,props.mode],()=>{controller?.abort();items.value=[];detail.value=null;notice.value='';page.value=1;filter.value='user';load()},{immediate:true});watch([search,filter,sort],()=>page.value=1)
onMounted(()=>{timer=setInterval(()=>{if(auto.value&&props.mode==='processes'&&!document.hidden&&!loading.value&&!busy.value)load()},10000)})
onUnmounted(()=>{disposed=true;generation++;controller?.abort();clearInterval(timer)})
</script>
